import React, { useState } from 'react';
import { Map, MapPin, ChevronRight, ChevronLeft, Search, Box, Info } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); // 'ZONES', 'AREAS', or 'BINS'
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- MOCK DATA STRUCTURE ---
  const data = [
    {
      id: 'Z-101', name: 'NORTH_SECTOR', code: 'NS-01', 
      areas: [
        { id: 'A-101-1', name: 'Hillside Drive', location: 'Upper North', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-101-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-202', name: 'CENTRAL_HUB', code: 'CH-02', 
      areas: [
        { id: 'A-202-1', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102', 'BN-103', 'BN-104'] },
        { id: 'A-202-2', name: 'Shopping Plaza', location: 'Midtown', code: 'SPZ-09', bins: ['BN-201', 'BN-205'] }
      ]
    }
  ];

  // --- FILTER LOGIC ---
  const filteredZones = data.filter(z => 
    z.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    z.code.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const filteredAreas = selectedZone?.areas.filter(a => 
    a.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // --- NAVIGATION HANDLERS ---
  const handleZoneClick = (zone) => {
    setSelectedZone(zone);
    setViewLevel('AREAS');
    setSearchQuery('');
  };

  const handleAreaClick = (area) => {
    setSelectedArea(area);
    setViewLevel('BINS');
    setSearchQuery('');
  };

  // --- UI COMPONENTS ---

  const SearchBar = ({ placeholder }) => (
    <div className="relative mb-6">
      <Search className="absolute left-4 top-3 text-[#47510B] opacity-40" size={18} />
      <input 
        type="text" 
        placeholder={placeholder}
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
        className="w-full bg-[#FDFAD8] border-[4px] border-[#47510B] rounded-2xl py-3 pl-12 pr-4 font-black text-sm uppercase focus:outline-none placeholder:text-[#47510B]/30 shadow-[4px_4px_0_0_#47510B]"
      />
    </div>
  );

  return (
    <div className="w-full animate-slot flex flex-col gap-6">

      {/* 1. ZONES VIEW (MASTER LIST) */}
      {viewLevel === 'ZONES' && (
        <>
          <div className="bg-[#A1AED1] p-4 border-[6px] border-[#47510B] rounded-2xl flex items-center gap-3 mb-2 shadow-[4px_4px_0_0_#47510B]">
            <Map className="text-[#AB1717]" />
            <h2 className="text-xl font-black italic text-[#47510B] uppercase">02_ZONE_DIRECTORIES</h2>
          </div>
          <SearchBar placeholder="SEARCH_BY_ZONE_NAME_OR_CODE..." />
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {filteredZones.map(zone => (
              <button key={zone.id} onClick={() => handleZoneClick(zone)} className="bg-white border-[6px] border-[#47510B] p-6 rounded-[30px] flex justify-between items-center shadow-[8px_8px_0_0_#CAD23C] hover:translate-x-2 transition-all group">
                <div className="text-left">
                  <span className="text-[10px] font-black text-[#AB1717] tracking-widest uppercase italic">{zone.code}</span>
                  <h3 className="text-2xl font-black text-[#47510B] italic uppercase leading-none">{zone.name}</h3>
                  <p className="text-[10px] font-bold text-[#47510B]/50 mt-2 uppercase">{zone.areas.length} AREAS REGISTERED</p>
                </div>
                <ChevronRight size={32} className="text-[#47510B] group-hover:translate-x-2 transition-transform" />
              </button>
            ))}
          </div>
        </>
      )}

      {/* 2. AREAS VIEW (DRILL DOWN) */}
      {viewLevel === 'AREAS' && (
        <>
          <div className="flex items-center gap-4 bg-[#47510B] p-4 rounded-2xl shadow-[4px_4px_0_0_#CAD23C]">
            <button onClick={() => setViewLevel('ZONES')} className="bg-[#FDFAD8] p-2 rounded-lg border-2 border-[#47510B] hover:bg-[#CAD23C] transition-colors">
              <ChevronLeft size={20} />
            </button>
            <h2 className="text-xl font-black italic text-[#CAD23C] uppercase leading-none">{selectedZone.name} <span className="text-[#FDFAD8]/40">/ AREAS</span></h2>
          </div>
          <SearchBar placeholder={`SEARCH_AREAS_IN_${selectedZone.name}...`} />
          <div className="grid grid-cols-1 gap-4">
            {filteredAreas.map(area => (
              <button key={area.id} onClick={() => handleAreaClick(area)} className="bg-white border-[6px] border-[#47510B] p-5 rounded-[25px] flex flex-wrap justify-between items-center shadow-[6px_6px_0_0_#A1AED1] hover:bg-[#FDFAD8] transition-all">
                <div className="flex items-center gap-4">
                  <div className="bg-[#AB1717] p-3 rounded-xl border-2 border-[#47510B]">
                    <MapPin className="text-[#FDFAD8]" size={20} />
                  </div>
                  <div className="text-left">
                    <h4 className="text-lg font-black text-[#47510B] uppercase italic">{area.name}</h4>
                    <p className="text-[10px] font-bold text-[#47510B]/60 uppercase tracking-tighter">Loc: {area.location} | Code: {area.code}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <span className="text-xs font-black text-[#47510B] bg-[#CAD23C] px-3 py-1 rounded-full border-2 border-[#47510B]">{area.bins.length} BINS</span>
                  <ChevronRight size={24} className="text-[#47510B]" />
                </div>
              </button>
            ))}
          </div>
        </>
      )}

      {/* 3. BINS LIST VIEW (DETAIL LEVEL) */}
      {viewLevel === 'BINS' && (
        <div className="animate-slot">
          <div className="flex items-center gap-4 bg-[#AB1717] p-4 rounded-2xl shadow-[4px_4px_0_0_#47510B] mb-6">
            <button onClick={() => setViewLevel('AREAS')} className="bg-[#FDFAD8] p-2 rounded-lg border-2 border-[#47510B] hover:bg-[#CAD23C] transition-colors">
              <ChevronLeft size={20} />
            </button>
            <h2 className="text-xl font-black italic text-[#FDFAD8] uppercase leading-none">{selectedArea.name} <span className="text-[#CAD23C]">/ TELEMETRY_NODES</span></h2>
          </div>

          <div className="bg-white border-[8px] border-[#47510B] rounded-[40px] p-8 shadow-2xl">
             <div className="flex items-center gap-2 mb-6 border-b-4 border-[#47510B]/10 pb-4">
                <Box className="text-[#AB1717]" />
                <h3 className="font-black text-[#47510B] uppercase tracking-widest italic">HARDWARE_ID_LISTING</h3>
             </div>
             <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                {selectedArea.bins.map(binId => (
                  <div key={binId} className="bg-[#FDFAD8] border-[4px] border-[#47510B] p-4 rounded-2xl flex flex-col items-center gap-2 hover:bg-[#CAD23C] transition-colors">
                    <span className="text-[9px] font-black text-[#AB1717] uppercase opacity-60 italic leading-none">Node_Serial</span>
                    <span className="text-sm font-black text-[#47510B]">{binId}</span>
                  </div>
                ))}
             </div>
             <div className="mt-8 bg-[#47510B] p-4 rounded-xl flex items-center gap-3">
                <Info size={16} className="text-[#CAD23C]" />
                <p className="text-[10px] font-bold text-[#FDFAD8] uppercase">Total Units active in this Area are linked to real-time telemetry sensors.</p>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AreasZonesTab;
